// Store values
localStorage.setItem("username", "Alex");
localStorage.setItem("theme", "dark");

// Retrieve values
let name = localStorage.getItem("username");
console.log(name);  // "Alex"

// Remove one
localStorage.removeItem("theme");

// Check all stored data
console.log(localStorage.length);  // 1
console.log(localStorage.key(0));  // "username"

// Clear everything
localStorage.clear();

// Same API as localStorage
sessionStorage.setItem("step", "2");
console.log(sessionStorage.getItem("step"));  // "2"

// Each tab has its own session storage
// Tab A: sessionStorage.setItem("id", "A")
// Tab B: sessionStorage.getItem("id")  // null!

// Data disappears when tab closes
// Close the tab → reopen → getItem returns null

// Save a to-do list
let todos = [
  { text: "Learn JS", done: true },
  { text: "Build project", done: false }
];

localStorage.setItem("todos", JSON.stringify(todos));

// Retrieve and parse
let stored = JSON.parse(localStorage.getItem("todos"));
console.log(stored[0].text);  // "Learn JS"

// Safe parsing with error handling
function safeParse(key) {
  try {
    return JSON.parse(localStorage.getItem(key));
  } catch {
    return null;
  }
}

let data = safeParse("todos");
